mapper.select:
SELECT examStudentQuestionMemory.*
, examCourse.course_name AS courseName
, examQuestion.question_title AS questionTitle
FROM exam_student_question_memory examStudentQuestionMemory
LEFT JOIN exam_course examCourse ON examStudentQuestionMemory.course_id = examCourse.id
LEFT JOIN exam_question examQuestion ON examStudentQuestionMemory.question_id = examQuestion.id
WHERE examStudentQuestionMemory.student_id = #{studentId}
  AND examStudentQuestionMemory.status = 1
  AND examStudentQuestionMemory.next_review_time <= #{now}
  AND examStudentQuestionMemory.course_id = #{courseId}
ORDER BY examStudentQuestionMemory.recommend_priority DESC, examStudentQuestionMemory.next_review_time ASC
LIMIT #{limit}
